CREATE SCHEMA IF NOT EXISTS truss; COMMENT ON SCHEMA truss IS 'truss-layout 0.2'; CREATE TABLE truss.setting (key text PRIMARY KEY, value jsonb NOT NULL); INSERT INTO truss.setting VALUES ('journal_mode', '"engine"'); INSERT INTO truss.setting VALUES ('key_reuse', '"forbid"'); CREATE TABLE truss.module_access (module text PRIMARY KEY, reader_role text NOT NULL, writer_role text NOT NULL, CONSTRAINT module_access_roles_differ CHECK (reader_role <> writer_role)); CREATE TABLE truss.schema_rev (rev int PRIMARY KEY, accepted_at timestamptz NOT NULL DEFAULT now(), report jsonb NOT NULL, origin jsonb NOT NULL DEFAULT ('{}'::jsonb), CONSTRAINT schema_rev_origin_is_object CHECK (jsonb_typeof(origin) = 'object')); INSERT INTO truss.schema_rev VALUES (0, now(), '{}'); CREATE TABLE truss.schema_head (id int PRIMARY KEY CHECK (id = 1), rev int NOT NULL REFERENCES truss.schema_rev (rev)); INSERT INTO truss.schema_head VALUES (1, 0); CREATE TABLE truss.schema_doc (rev int NOT NULL REFERENCES truss.schema_rev (rev), ord int NOT NULL, doc_id text NOT NULL, doc_revision text NOT NULL, umf_version text NOT NULL, content_sha256 text NOT NULL, document text NOT NULL, validation jsonb NOT NULL, PRIMARY KEY (rev, ord), UNIQUE (rev, doc_id)); CREATE TABLE truss.schema_change (rev int NOT NULL REFERENCES truss.schema_rev (rev), seq int NOT NULL, kind text NOT NULL CHECK (kind IN ('type', 'prop', 'rel')), def_id int NOT NULL, before jsonb NOT NULL, after jsonb NOT NULL, PRIMARY KEY (rev, seq)); CREATE TABLE truss.type_def (type_id int PRIMARY KEY, module text NOT NULL, element text NOT NULL, kind text NOT NULL, provisional boolean NOT NULL DEFAULT false, since_rev int NOT NULL REFERENCES truss.schema_rev (rev), doc_ord int, retired_rev int REFERENCES truss.schema_rev (rev), UNIQUE (module, element), FOREIGN KEY (since_rev, doc_ord) REFERENCES truss.schema_doc (rev, ord)); CREATE TABLE truss.prop_def (prop_id int PRIMARY KEY, type_id int NOT NULL REFERENCES truss.type_def (type_id), element text NOT NULL, name text NOT NULL, scalar_type text, nullability text NOT NULL, cardinality text NOT NULL, facets jsonb, item jsonb, home text NOT NULL DEFAULT 'json' CHECK (home IN ('json', 'row')), since_rev int NOT NULL REFERENCES truss.schema_rev (rev), doc_ord int NOT NULL, retired_rev int REFERENCES truss.schema_rev (rev), UNIQUE (type_id, name), UNIQUE (type_id, element), FOREIGN KEY (since_rev, doc_ord) REFERENCES truss.schema_doc (rev, ord)); CREATE TABLE truss.key_def (type_id int NOT NULL REFERENCES truss.type_def (type_id), key_id text NOT NULL, key_num smallint NOT NULL, prop_ids int[] NOT NULL, is_primary boolean NOT NULL, since_rev int NOT NULL REFERENCES truss.schema_rev (rev), retired_rev int REFERENCES truss.schema_rev (rev), PRIMARY KEY (type_id, key_id), UNIQUE (type_id, key_num)); CREATE TABLE truss.rel_def (rel_type_id int PRIMARY KEY, module text NOT NULL, rel_id text NOT NULL, name text NOT NULL, source_min int NOT NULL, source_max int, target_min int NOT NULL, target_max int, lifecycle text NOT NULL, directed boolean NOT NULL, target_key text, composition boolean NOT NULL DEFAULT false, assoc_type_id int REFERENCES truss.type_def (type_id), inverse text, since_rev int NOT NULL REFERENCES truss.schema_rev (rev), doc_ord int NOT NULL, retired_rev int REFERENCES truss.schema_rev (rev), UNIQUE (module, rel_id), FOREIGN KEY (since_rev, doc_ord) REFERENCES truss.schema_doc (rev, ord)); CREATE TABLE truss.rel_endpoint (rel_type_id int NOT NULL REFERENCES truss.rel_def (rel_type_id), source_type int NOT NULL REFERENCES truss.type_def (type_id), target_type int NOT NULL REFERENCES truss.type_def (type_id), PRIMARY KEY (rel_type_id, source_type, target_type)); CREATE SEQUENCE truss.id_seq; CREATE TABLE truss.object (id bigint NOT NULL DEFAULT nextval('truss.id_seq'), type_id int NOT NULL REFERENCES truss.type_def (type_id), props jsonb NOT NULL DEFAULT ('{}'::jsonb), retained jsonb, root_id bigint, root_type int, rev int NOT NULL REFERENCES truss.schema_rev (rev), ver bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), updated_at timestamptz NOT NULL DEFAULT clock_timestamp(), CONSTRAINT object_pkey PRIMARY KEY (id, type_id), CONSTRAINT object_props_is_object CHECK (jsonb_typeof(props) = 'object'), CONSTRAINT object_retained_is_object CHECK (retained IS NULL OR jsonb_typeof(retained) = 'object'), CONSTRAINT object_root_both_or_neither CHECK ((root_id IS NULL) = (root_type IS NULL)), CONSTRAINT object_root_fk FOREIGN KEY (root_id, root_type) REFERENCES truss.object (id, type_id) ON DELETE RESTRICT); CREATE INDEX object_type_id ON truss.object USING btree (type_id, id); CREATE TABLE truss.object_key (type_id int NOT NULL, key_num smallint NOT NULL, k text NOT NULL COLLATE "C", object_id bigint NOT NULL, CONSTRAINT object_key_pkey PRIMARY KEY (type_id, key_num, k), CONSTRAINT object_key_one_per_object UNIQUE (object_id, type_id, key_num), CONSTRAINT object_key_def_fk FOREIGN KEY (type_id, key_num) REFERENCES truss.key_def (type_id, key_num), CONSTRAINT object_key_object_fk FOREIGN KEY (object_id, type_id) REFERENCES truss.object (id, type_id) ON DELETE CASCADE); CREATE TABLE truss.edge (id bigint PRIMARY KEY DEFAULT nextval('truss.id_seq'), rel_type_id int NOT NULL, source_id bigint NOT NULL, source_type int NOT NULL, target_id bigint NOT NULL, target_type int NOT NULL, props jsonb NOT NULL DEFAULT ('{}'::jsonb), order_key text COLLATE "C", rev int NOT NULL REFERENCES truss.schema_rev (rev), ver bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), updated_at timestamptz NOT NULL DEFAULT clock_timestamp(), CONSTRAINT edge_props_is_object CHECK (jsonb_typeof(props) = 'object'), CONSTRAINT edge_source_fk FOREIGN KEY (source_id, source_type) REFERENCES truss.object (id, type_id) ON DELETE RESTRICT, CONSTRAINT edge_target_fk FOREIGN KEY (target_id, target_type) REFERENCES truss.object (id, type_id) ON DELETE RESTRICT, CONSTRAINT edge_endpoint_types_fk FOREIGN KEY (rel_type_id, source_type, target_type) REFERENCES truss.rel_endpoint (rel_type_id, source_type, target_type)); CREATE UNIQUE INDEX edge_out ON truss.edge USING btree (source_id, rel_type_id, target_id) INCLUDE (target_type); CREATE INDEX edge_in ON truss.edge USING btree (target_id, rel_type_id) INCLUDE (source_id, source_type); CREATE TABLE truss.edge_limit (rel_type_id bigint NOT NULL, side char(1) NOT NULL CHECK (side IN ('s', 't')), endpoint_id bigint NOT NULL, edge_id bigint NOT NULL REFERENCES truss.edge (id) ON DELETE CASCADE, PRIMARY KEY (rel_type_id, side, endpoint_id)); CREATE INDEX edge_limit_edge ON truss.edge_limit USING btree (edge_id); CREATE TABLE truss.key_tombstone (entity_kind char(1) NOT NULL CHECK (entity_kind IN ('o', 'e')), type_id int NOT NULL, key_num smallint NOT NULL, k text NOT NULL COLLATE "C", entity_id bigint NOT NULL, ver bigint NOT NULL, at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY (entity_kind, type_id, key_num, k), CONSTRAINT key_tombstone_edge_key CHECK (entity_kind = 'o' OR key_num = 0)); CREATE TABLE truss.record_source (entity_kind char(1) NOT NULL CHECK (entity_kind IN ('o', 'e')), entity_id bigint NOT NULL, load_id text NOT NULL, source jsonb NOT NULL DEFAULT ('{}'::jsonb), imported_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY (entity_kind, entity_id), CONSTRAINT record_source_is_object CHECK (jsonb_typeof(source) = 'object')); CREATE INDEX record_source_load ON truss.record_source USING btree (load_id); CREATE TABLE truss.feed_consumer (consumer text PRIMARY KEY, xid xid8 NOT NULL, seq bigint NOT NULL, updated_at timestamptz NOT NULL DEFAULT clock_timestamp()); CREATE SEQUENCE truss.journal_seq; CREATE TABLE truss.journal (seq bigint NOT NULL DEFAULT nextval('truss.journal_seq'), at timestamptz NOT NULL DEFAULT clock_timestamp(), xid xid8 NOT NULL DEFAULT pg_current_xact_id(), entity_kind char(1) NOT NULL CHECK (entity_kind IN ('o', 'e')), entity_id bigint NOT NULL, entity_type int NOT NULL, ver bigint NOT NULL, op text NOT NULL CHECK (op IN ('create', 'update', 'delete', 'retain', 'rebind', 'transform')), prop_id int, old_value jsonb, new_value jsonb, rev int NOT NULL, origin jsonb NOT NULL DEFAULT ('{}'::jsonb), CONSTRAINT journal_pkey PRIMARY KEY (at, seq), CONSTRAINT journal_origin_is_object CHECK (jsonb_typeof(origin) = 'object')) PARTITION BY RANGE(at); CREATE INDEX journal_entity ON truss.journal USING btree (entity_kind, entity_id, ver); CREATE INDEX journal_feed ON truss.journal USING btree (xid, seq); CREATE INDEX journal_request ON truss.journal USING btree ((origin #>> '{request,id}')) WHERE origin ? 'request'
